/**
 * Generates src/generated/*.ts from the OpenAPI document and the offline
 * tables of @veriport/shared (the same document served at /openapi.json).
 * Run `pnpm generate` after a change to the API; `pnpm generate --check`
 * fails when the committed files are stale (prepublishOnly runs it). Also
 * writes the Python package's tables (../sdk-python/src/veriport/_tables.py)
 * so that both SDKs read one source.
 *
 * The published package has no runtime dependency: everything it needs from
 * the shared package is copied into the generated files at generation time.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { OpenApiDocument, Operation } from '@veriport/shared';

// The shared package is TypeScript source without a "type" field: tsx serves it as CommonJS, whose re-exports an ESM named import cannot see; require() sees them all.
const { API_VERSION, IBAN_COUNTRIES, IBAN_REGISTRY, REQUEST_MAX_BYTES, VAT_COUNTRIES, VAT_FORMATS, openApiDocument } = createRequire(import.meta.url)('@veriport/shared') as typeof import('@veriport/shared');

type Schema = Record<string, unknown>;

const here = dirname(fileURLToPath(import.meta.url));
const OUT = join(here, '..', 'src', 'generated');
const PY_OUT = join(here, '..', '..', 'sdk-python', 'src', 'veriport');
const check = process.argv.includes('--check');
const HEADER = `// Generated by scripts/generate.ts from the Veriport OpenAPI document (API version ${API_VERSION}). Do not edit; run \`pnpm generate\`.\n`;

const pascal = (s: string) => s.replace(/(^|[^A-Za-z0-9])([a-z0-9])/g, (_, __, c: string) => c.toUpperCase());

function tsType(schema: Schema | undefined, indent = ''): string {
  if (!schema) return 'unknown';
  if (typeof schema.$ref === 'string') return String(schema.$ref).split('/').pop() as string;
  if (Array.isArray(schema.oneOf)) return (schema.oneOf as Schema[]).map((s) => tsType(s, indent)).join(' | ');
  if (Array.isArray(schema.anyOf)) return (schema.anyOf as Schema[]).map((s) => tsType(s, indent)).join(' | ');
  if (Array.isArray(schema.enum)) return (schema.enum as unknown[]).map((e) => JSON.stringify(e)).join(' | ');
  const types = Array.isArray(schema.type) ? (schema.type as string[]) : [String(schema.type ?? 'object')];
  const nullable = types.includes('null');
  const base = types.filter((t) => t !== 'null')[0] ?? 'object';
  let out: string;
  if (base === 'string') out = 'string';
  else if (base === 'number' || base === 'integer') out = 'number';
  else if (base === 'boolean') out = 'boolean';
  else if (base === 'array') out = `Array<${tsType(schema.items as Schema, indent)}>`;
  else if (base === 'object') {
    const props = (schema.properties ?? {}) as Record<string, Schema>;
    const required = new Set((schema.required as string[] | undefined) ?? []);
    const entries = Object.entries(props);
    if (!entries.length) out = schema.additionalProperties && typeof schema.additionalProperties === 'object' ? `Record<string, ${tsType(schema.additionalProperties as Schema, indent)}>` : 'Record<string, unknown>';
    else {
      const inner = indent + '  ';
      out = `{\n${entries.map(([k, v]) => `${inner}${v.description ? `/** ${String(v.description).replace(/\*\//g, '* /').replace(/\n/g, ' ')} */\n${inner}` : ''}${JSON.stringify(k).replace(/^"([A-Za-z_$][A-Za-z0-9_$]*)"$/, '$1')}${required.has(k) ? '' : '?'}: ${tsType(v, inner)};`).join('\n')}\n${indent}}`;
    }
  } else out = 'unknown';
  return nullable ? `${out} | null` : out;
}

function generateOpenApi(doc: OpenApiDocument): string {
  const lines: string[] = [HEADER, `export const API_VERSION = ${JSON.stringify(doc.info.version)};`, `export const DEFAULT_BASE_URL = ${JSON.stringify(doc.servers[0].url)};`, '/** The largest request body the API accepts (bytes); a larger one is refused by the hosting platform before the API runs. */', `export const REQUEST_MAX_BYTES = ${REQUEST_MAX_BYTES};`, ''];
  lines.push('// ---- Component schemas');
  for (const [name, schema] of Object.entries(doc.components.schemas)) {
    lines.push(`${schema.description ? `/** ${String(schema.description).replace(/\n/g, ' ')} */\n` : ''}export type ${name} = ${tsType(schema as Schema)};`, '');
  }
  lines.push('// ---- Operations');
  const ops: Array<{ id: string; method: string; path: string; op: Operation }> = [];
  for (const [path, methods] of Object.entries(doc.paths)) for (const [method, op] of Object.entries(methods)) if (op) ops.push({ id: op.operationId, method, path, op });
  const table: string[] = [];
  const iface: string[] = [];
  for (const { id, method, path, op } of ops) {
    const P = pascal(id);
    const params = (op.parameters ?? []).filter((p) => p.in !== 'header');
    const paramsType = params.length ? `{\n${params.map((p) => `  /** ${p.description.replace(/\n/g, ' ')} */\n  ${p.name}${p.required ? '' : '?'}: ${tsType(p.schema as Schema, '  ')};`).join('\n')}\n}` : 'Record<string, never>';
    lines.push(`/** ${op.summary} — ${method.toUpperCase()} ${path}. Tiers: ${op['x-tiers'].join(', ')}. Cost: ${op['x-cost'].replace(/\n/g, ' ')} */`, `export type ${P}Params = ${paramsType};`);
    const body = op.requestBody?.content['application/json']?.schema as Schema | undefined;
    // Operations that take a file (the e-invoice validate and parse calls): the media types they accept.
    const bodyTypes = Object.keys(op.requestBody?.content ?? {});
    lines.push(`export type ${P}Body = ${body ? tsType(body) : 'never'};`);
    const ok = op.responses['200']?.content?.['application/json']?.schema as Schema | undefined;
    lines.push(`export type ${P}Response = ${ok ? tsType(ok) : 'unknown'};`, '');
    const anonymous = Boolean(op.security?.some((s) => Object.keys(s).length === 0));
    table.push(`  ${id}: { method: ${JSON.stringify(method.toUpperCase())}, path: ${JSON.stringify(path)}, pathParams: ${JSON.stringify(params.filter((p) => p.in === 'path').map((p) => p.name))}, query: ${JSON.stringify(params.filter((p) => p.in === 'query').map((p) => p.name))}, hasBody: ${Boolean(body)}, bodyTypes: ${JSON.stringify(bodyTypes)}, anonymous: ${anonymous}, tiers: ${JSON.stringify(op['x-tiers'])}, cost: ${JSON.stringify(op['x-cost'])} },`);
    iface.push(`  ${id}: { params: ${P}Params; body: ${P}Body; response: ${P}Response };`);
  }
  lines.push('/** Each operation: its parameter, body and response types. */', `export interface Operations {\n${iface.join('\n')}\n}`, '');
  lines.push('export interface OperationSpec { method: "GET" | "POST"; path: string; pathParams: string[]; query: string[]; hasBody: boolean; bodyTypes: string[]; anonymous: boolean; tiers: string[]; cost: string }', '');
  lines.push('/** The routing table of the client: how each operation is sent. */', `export const OPERATIONS: Record<keyof Operations, OperationSpec> = {\n${table.join('\n')}\n};`, '');
  return lines.join('\n');
}

function generateVatFormats(): string {
  const rows = VAT_COUNTRIES.map((c) => {
    const f = VAT_FORMATS[c];
    return `  ${c}: { country: ${JSON.stringify(c)}, name: ${JSON.stringify(f.name)}, structure: ${JSON.stringify(f.structure)}, example: ${JSON.stringify(f.example)}, pattern: ${JSON.stringify(f.pattern.source)}, publicChecksum: ${f.checksum !== null} },`;
  });
  return `${HEADER}\n/** The structure of each EU VAT number after its two-letter prefix (the Commission's VIES FAQ, Q11); \`publicChecksum\` says whether the API verifies a national check digit before asking VIES. */\nexport interface VatFormat { country: string; name: string; structure: string; example: string; pattern: string; publicChecksum: boolean }\n\nexport const VAT_FORMATS: Record<string, VatFormat> = {\n${rows.join('\n')}\n};\n`;
}

function generateIbanRegistry(): string {
  const rows = IBAN_COUNTRIES.map((c) => {
    const r = IBAN_REGISTRY[c];
    return `  ${c}: { code: ${JSON.stringify(c)}, name: ${JSON.stringify(r.name)}, length: ${r.length}, bban: ${JSON.stringify(r.bban)}, sepa: ${r.sepa}${r.sepaSince ? `, sepaSince: ${JSON.stringify(r.sepaSince)}` : ''}${r.bankId ? `, bankId: ${JSON.stringify(r.bankId)}` : ''}${r.branchId ? `, branchId: ${JSON.stringify(r.branchId)}` : ''} },`;
  });
  return `${HEADER}\n/** The SWIFT IBAN Registry (ISO 13616) as the API transcribed it: length, BBAN notation (\`4!n\` four digits, \`4!a\` four letters, \`12!c\` twelve alphanumerics), SEPA flag and, where the registry defines them, the bank and branch identifier positions (0-based start in the BBAN, length). */\nexport interface IbanCountry { code: string; name: string; length: number; bban: string; sepa: boolean; sepaSince?: string; bankId?: [number, number]; branchId?: [number, number] }\n\nexport const IBAN_REGISTRY: Record<string, IbanCountry> = {\n${rows.join('\n')}\n};\n`;
}

function generatePythonTables(): string {
  const vat = VAT_COUNTRIES.map((c) => {
    const f = VAT_FORMATS[c];
    return `    ${JSON.stringify(c)}: {"name": ${JSON.stringify(f.name)}, "structure": ${JSON.stringify(f.structure)}, "example": ${JSON.stringify(f.example)}, "pattern": ${JSON.stringify(f.pattern.source)}, "public_checksum": ${f.checksum !== null ? 'True' : 'False'}},`;
  });
  const iban = IBAN_COUNTRIES.map((c) => {
    const r = IBAN_REGISTRY[c];
    return `    ${JSON.stringify(c)}: {"name": ${JSON.stringify(r.name)}, "length": ${r.length}, "bban": ${JSON.stringify(r.bban)}, "sepa": ${r.sepa ? 'True' : 'False'}, "sepa_since": ${r.sepaSince ? JSON.stringify(r.sepaSince) : 'None'}, "bank_id": ${r.bankId ? `(${r.bankId[0]}, ${r.bankId[1]})` : 'None'}, "branch_id": ${r.branchId ? `(${r.branchId[0]}, ${r.branchId[1]})` : 'None'}},`;
  });
  return `# Generated by packages/sdk-ts/scripts/generate.ts from the Veriport shared tables (API version ${API_VERSION}). Do not edit.\n\nAPI_VERSION = ${JSON.stringify(API_VERSION)}\n\n# The largest request body the API accepts (bytes); a larger one is refused by the hosting platform before the API runs.\nREQUEST_MAX_BYTES = ${REQUEST_MAX_BYTES}\n\n# The structure of each EU VAT number after its two-letter prefix (VIES FAQ, Q11).\nVAT_FORMATS = {\n${vat.join('\n')}\n}\n\n# The SWIFT IBAN Registry (ISO 13616): length, BBAN notation, SEPA flag, bank and branch positions (0-based start, length).\nIBAN_REGISTRY = {\n${iban.join('\n')}\n}\n`;
}

const files: Array<[string, string]> = [
  [join(OUT, 'openapi.ts'), generateOpenApi(openApiDocument())],
  [join(OUT, 'vat-formats.ts'), generateVatFormats()],
  [join(OUT, 'iban-registry.ts'), generateIbanRegistry()],
  [join(PY_OUT, '_tables.py'), generatePythonTables()],
];

let stale = 0;
for (const [file, content] of files) {
  mkdirSync(dirname(file), { recursive: true });
  let current = '';
  try {
    current = readFileSync(file, 'utf8');
  } catch {
    current = '';
  }
  if (current === content) continue;
  if (check) {
    console.error(`stale: ${file}`);
    stale++;
  } else {
    writeFileSync(file, content);
    console.log(`wrote ${file}`);
  }
}
if (check && stale) process.exit(1);
if (check) console.log('generated files are up to date');
